/// Opens a job, or reopens a known one to resume it; opener to peer, control connection (SPEC.md §11.3, §11.5).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct JobOpen {
    /// The job's id, chosen by the opener (SPEC.md §11.1).
    pub job_id: [u8; 16],
    /// A `JOB_*` kind, as seen by the node that receives this.
    pub kind: u8,
    /// A `POLICY_*`.
    pub policy: u8,
    /// `JF_*` bits (SPEC.md §11.8).
    pub flags: u32,
    /// Upload: the destination; download: the source.
    pub root: String,
    /// `JOB_COPY`: the source.
    pub src: Option<String>,
    /// `JOB_DOWNLOAD`: the credit the opener grants, in bytes (SPEC.md §12.4).
    pub credit: Option<u64>,
}

impl Message for JobOpen {
    const NAME: &'static str = "JobOpen";

    fn encode_into(&self, w: &mut Writer) -> Result<(), EncodeError> {
        w.fixed(&self.job_id);
        w.u8(self.kind);
        w.u8(self.policy);
        w.u32(self.flags);
        w.str(&self.root)?;
        let mut ext_n: u16 = 0;
        if self.src.is_some() { ext_n += 1; }
        if self.credit.is_some() { ext_n += 1; }
        w.u16(ext_n);
        if let Some(v) = &self.src { w.ext(1, |w| { w.str(v) })?; }
        if let Some(v) = &self.credit { w.ext(2, |w| { w.u64(*v); Ok(()) })?; }
        Ok(())
    }

    fn decode(b: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(b);
        let mut m = Self::default();
        m.job_id = r.fixed::<16>()?;
        m.kind = r.u8()?;
        m.policy = r.u8()?;
        m.flags = r.u32()?;
        m.root = r.str()?;
        let ext_n = r.u16()?;
        for _ in 0..ext_n {
            let tag = r.u16()?;
            let len = r.u32()? as usize;
            let v = r.take(len)?;
            match tag {
                1 => {
                    if m.src.is_some() { return Err(DecodeError::DupExt(1)); }
                    let mut vr = Reader::new(v);
                    m.src = Some(vr.str()?);
                    vr.finish()?;
                }
                2 => {
                    if m.credit.is_some() { return Err(DecodeError::DupExt(2)); }
                    let mut vr = Reader::new(v);
                    m.credit = Some(vr.u64()?);
                    vr.finish()?;
                }
                _ => {}
            }
        }
        r.finish()?;
        Ok(m)
    }
}

