/// A job's progress: sent by the receiver every 250 ms, IGNORABLE; also the reply body of `job.status` and the job-starting methods (SPEC.md §7.1, §16.9).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Status {
    /// The job.
    pub job_id: [u8; 16],
    /// Files finished.
    pub files_done: u32,
    /// Files in the job; 0 while unknown.
    pub files_total: u32,
    /// Bytes the receiver has received.
    pub bytes_received: u64,
    /// Bytes durable on the receiver.
    pub bytes_durable: u64,
    /// Bytes in the job; 0 while unknown.
    pub bytes_total: u64,
    /// The receiver's own `BN_*` bottleneck.
    pub bottleneck: u8,
    /// The receiver's write workers.
    pub workers: u8,
    /// Data lanes in use.
    pub lanes: u8,
    /// Reserved for the sender's sequential choice (SPEC.md §16); version 1 receivers send 0.
    pub sequential: u8,
    /// The current step; on a failed job, the cause.
    pub current: Option<String>,
    /// RPC replies: 0 running, 1 finished OK, 2 failed (SPEC.md §7.1).
    pub state: Option<u8>,
    /// `job.run`: the finished operation's reply body, at most 128 KiB (SPEC.md §7.1.1).
    pub result: Option<Vec<u8>>,
    /// A failed job's `ERR_*` code.
    pub code: Option<u16>,
    /// Durable-by-log: done files not yet durable in place; absent means 0 (SPEC.md §15.7).
    pub unswept: Option<u32>,
}

impl Message for Status {
    const NAME: &'static str = "Status";

    fn encode_into(&self, w: &mut Writer) -> Result<(), EncodeError> {
        w.fixed(&self.job_id);
        w.u32(self.files_done);
        w.u32(self.files_total);
        w.u64(self.bytes_received);
        w.u64(self.bytes_durable);
        w.u64(self.bytes_total);
        w.u8(self.bottleneck);
        w.u8(self.workers);
        w.u8(self.lanes);
        w.u8(self.sequential);
        let mut ext_n: u16 = 0;
        if self.current.is_some() { ext_n += 1; }
        if self.state.is_some() { ext_n += 1; }
        if self.result.is_some() { ext_n += 1; }
        if self.code.is_some() { ext_n += 1; }
        if self.unswept.is_some() { ext_n += 1; }
        w.u16(ext_n);
        if let Some(v) = &self.current { w.ext(1, |w| { w.str(v) })?; }
        if let Some(v) = &self.state { w.ext(2, |w| { w.u8(*v); Ok(()) })?; }
        if let Some(v) = &self.result { w.ext(3, |w| { w.bytes(v) })?; }
        if let Some(v) = &self.code { w.ext(4, |w| { w.u16(*v); Ok(()) })?; }
        if let Some(v) = &self.unswept { w.ext(5, |w| { w.u32(*v); Ok(()) })?; }
        Ok(())
    }

    fn decode(b: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(b);
        let mut m = Self::default();
        m.job_id = r.fixed::<16>()?;
        m.files_done = r.u32()?;
        m.files_total = r.u32()?;
        m.bytes_received = r.u64()?;
        m.bytes_durable = r.u64()?;
        m.bytes_total = r.u64()?;
        m.bottleneck = r.u8()?;
        m.workers = r.u8()?;
        m.lanes = r.u8()?;
        m.sequential = r.u8()?;
        let ext_n = r.u16()?;
        for _ in 0..ext_n {
            let tag = r.u16()?;
            let len = r.u32()? as usize;
            let v = r.take(len)?;
            match tag {
                1 => {
                    if m.current.is_some() { return Err(DecodeError::DupExt(1)); }
                    let mut vr = Reader::new(v);
                    m.current = Some(vr.str()?);
                    vr.finish()?;
                }
                2 => {
                    if m.state.is_some() { return Err(DecodeError::DupExt(2)); }
                    let mut vr = Reader::new(v);
                    m.state = Some(vr.u8()?);
                    vr.finish()?;
                }
                3 => {
                    if m.result.is_some() { return Err(DecodeError::DupExt(3)); }
                    let mut vr = Reader::new(v);
                    m.result = Some(vr.bytes()?);
                    vr.finish()?;
                }
                4 => {
                    if m.code.is_some() { return Err(DecodeError::DupExt(4)); }
                    let mut vr = Reader::new(v);
                    m.code = Some(vr.u16()?);
                    vr.finish()?;
                }
                5 => {
                    if m.unswept.is_some() { return Err(DecodeError::DupExt(5)); }
                    let mut vr = Reader::new(v);
                    m.unswept = Some(vr.u32()?);
                    vr.finish()?;
                }
                _ => {}
            }
        }
        r.finish()?;
        Ok(m)
    }
}

impl FrameMessage for Status {
    const TYPE: u8 = 0x2d;
}

