impl Message for ManifestEntry {
    const NAME: &'static str = "ManifestEntry";

    fn encode_into(&self, w: &mut Writer) -> Result<(), EncodeError> {
        w.u32(self.file_id);
        w.u8(self.kind);
        w.u32(self.mode);
        w.u64(self.size);
        w.u64(self.mtime);
        w.str(&self.path)?;
        let mut ext_n: u16 = 0;
        if self.root.is_some() { ext_n += 1; }
        w.u16(ext_n);
        if let Some(v) = &self.root { w.ext(1, |w| { w.fixed(v); Ok(()) })?; }
        Ok(())
    }

    fn decode(b: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(b);
        let mut m = Self::default();
        m.file_id = r.u32()?;
        m.kind = r.u8()?;
        m.mode = r.u32()?;
        m.size = r.u64()?;
        m.mtime = r.u64()?;
        m.path = r.str()?;
        let ext_n = r.u16()?;
        for _ in 0..ext_n {
            let tag = r.u16()?;
            let len = r.u32()? as usize;
            let v = r.take(len)?;
            match tag {
                1 => {
                    if m.root.is_some() { return Err(DecodeError::DupExt(1)); }
                    let mut vr = Reader::new(v);
                    m.root = Some(vr.fixed::<32>()?);
                    vr.finish()?;
                }
                _ => {}
            }
        }
        r.finish()?;
        Ok(m)
    }
}

