/// Journal record kind 2: one sync batch (SPEC.md §14.2). Never on the wire.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct JnlBatch {
    /// Files now done; their ranges are dropped.
    pub files: Vec<FileRun>,
    /// Durable ranges added.
    pub ranges: Vec<FileRange>,
    /// Roots recorded.
    pub roots: Vec<RootItem>,
    /// Durable-by-log: the pack segment `pack.<n>` that holds this batch's `PackFile` records (SPEC.md §15.7).
    pub pack_segment: Option<u32>,
    /// Where those records start in the segment, in bytes.
    pub pack_offset: Option<u64>,
    /// Their length in bytes.
    pub pack_len: Option<u64>,
}

impl Message for JnlBatch {
    const NAME: &'static str = "JnlBatch";

    fn encode_into(&self, w: &mut Writer) -> Result<(), EncodeError> {
        w.records(&self.files)?;
        w.records(&self.ranges)?;
        w.records(&self.roots)?;
        let mut ext_n: u16 = 0;
        if self.pack_segment.is_some() { ext_n += 1; }
        if self.pack_offset.is_some() { ext_n += 1; }
        if self.pack_len.is_some() { ext_n += 1; }
        w.u16(ext_n);
        if let Some(v) = &self.pack_segment { w.ext(1, |w| { w.u32(*v); Ok(()) })?; }
        if let Some(v) = &self.pack_offset { w.ext(2, |w| { w.u64(*v); Ok(()) })?; }
        if let Some(v) = &self.pack_len { w.ext(3, |w| { w.u64(*v); Ok(()) })?; }
        Ok(())
    }

    fn decode(b: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(b);
        let mut m = Self::default();
        m.files = r.records::<FileRun>()?;
        m.ranges = r.records::<FileRange>()?;
        m.roots = r.records::<RootItem>()?;
        let ext_n = r.u16()?;
        for _ in 0..ext_n {
            let tag = r.u16()?;
            let len = r.u32()? as usize;
            let v = r.take(len)?;
            match tag {
                1 => {
                    if m.pack_segment.is_some() { return Err(DecodeError::DupExt(1)); }
                    let mut vr = Reader::new(v);
                    m.pack_segment = Some(vr.u32()?);
                    vr.finish()?;
                }
                2 => {
                    if m.pack_offset.is_some() { return Err(DecodeError::DupExt(2)); }
                    let mut vr = Reader::new(v);
                    m.pack_offset = Some(vr.u64()?);
                    vr.finish()?;
                }
                3 => {
                    if m.pack_len.is_some() { return Err(DecodeError::DupExt(3)); }
                    let mut vr = Reader::new(v);
                    m.pack_len = Some(vr.u64()?);
                    vr.finish()?;
                }
                _ => {}
            }
        }
        r.finish()?;
        Ok(m)
    }
}

/// Where a batch's `PackFile` records live; in journal snapshots only (SPEC.md §14.2, §15.7).
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct PackRef {
    /// The pack segment `pack.<n>`.
    pub segment: u32,
    /// Where the records start, in bytes.
    pub offset: u64,
    /// Their length in bytes.
    pub len: u64,
    /// The first file id the records cover.
    pub first_file: u32,
    /// File ids covered: `first_file..first_file + count`.
    pub count: u32,
}

impl Message for PackRef {
    const NAME: &'static str = "PackRef";

    fn encode_into(&self, w: &mut Writer) -> Result<(), EncodeError> {
        w.u32(self.segment);
        w.u64(self.offset);
        w.u64(self.len);
        w.u32(self.first_file);
        w.u32(self.count);
        w.u16(0);
        Ok(())
    }

    fn decode(b: &[u8]) -> Result<Self, DecodeError> {
        let mut r = Reader::new(b);
        let mut m = Self::default();
        m.segment = r.u32()?;
        m.offset = r.u64()?;
        m.len = r.u64()?;
        m.first_file = r.u32()?;
        m.count = r.u32()?;
        let ext_n = r.u16()?;
        for _ in 0..ext_n {
            let tag = r.u16()?;
            let len = r.u32()? as usize;
            let v = r.take(len)?;
            let _ = (tag, v);
        }
        r.finish()?;
        Ok(m)
    }
}

